 page.screenshot(path='/tmp/batch-prompt-'+ENGINE+'.png');dialog.get_by_role('button',name='Limpar seleção',exact=True).click();expect(dialog.get_by_role('button',name='Copiar prompt',exact=True)).to_be_disabled();expect(prompt).to_have_value('');dialog.get_by_role('button',name='Fechar',exact=True).click();page.set_viewport_size({'width':390,'height':844});main.locator('.gif-card-options').first.evaluate('e=>e.open=true');main.get_by_role('button',name='Criar demonstração',exact=True).first.click();expect(dialog.get_by_role('button',name='Carregar MP4 gerado')).to_be_visible();assert 'Afundo C/ Peso' in prompt.input_value() and 'Cadeira Abdutora' not in prompt.input_value();dialog.get_by_role('combobox',name='Ferramenta do prompt').select_option('antigravity');expect(phone).to_have_value('+55 85 90000-0000');dialog.get_by_role('combobox',name='Ferramenta do prompt').select_option('chatgpt');assert 'WhatsApp' not in prompt.input_value();expect(phone).to_be_hidden();dialog.get_by_role('button',name='Fechar',exact=True).click();assert page.evaluate('localStorage.getItem("treinoAlunos")')==before;assert not errors,errors;browser.close();print('PASS',ENGINE,': all-section unique batch choices and compound parts; copy one prompt; Drive-only upload instruction; Antigravity own-number WhatsApp instruction without student contact; contextual YouTube; 320px layout; existing per-exercise import intact')
